import '@testing-library/jest-dom/vitest'

import { render, screen, waitFor } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import { describe, expect, it, vi } from 'vitest'

const mocks = vi.hoisted(() => ({ getFamilyDashboard: vi.fn() }))
vi.mock('../../services/apiClient', () => ({ threePortalApi: mocks }))

import { FamilyDashboardPanel } from './FamilyDashboardPanel'

describe('FamilyDashboardPanel (Adult)', () => {
  it('hides family-management quick actions for an adult member', async () => {
    mocks.getFamilyDashboard.mockResolvedValue({
      data: {
        role: 'AdultMember',
        familyName: 'Silva Family',
        familyCode: null,
        memberCount: 4,
        minorCount: 2,
        nextAppointment: null,
        openCases: 0,
        approvedGuidanceCount: 0,
        familyDoctor: null,
        unreadNotifications: 0,
        recentActivity: [],
      },
    })

    render(<MemoryRouter><FamilyDashboardPanel /></MemoryRouter>)

    await waitFor(() => expect(screen.getByText('Book appointment')).toBeInTheDocument())
    expect(screen.queryByText('Add minor')).not.toBeInTheDocument()
    expect(screen.queryByText('Invite adult')).not.toBeInTheDocument()
    expect(screen.queryByText('Join requests')).not.toBeInTheDocument()
  })
})
